// SLV transport v2. Shared by the desktop and extension; uses standard Web Crypto.
// The browser copy is generated by scripts/sync-secure-channel.js.
(function (root) {
  const VERSION = "slv-secure-v2";
  const MAX_BYTES = 16384;
  const MAX_SEQUENCE = 1000000;
  const TTL_MS = 5 * 60 * 1000;
  const hex = bytes => Array.from(new Uint8Array(bytes), b => b.toString(16).padStart(2, "0")).join("");
  const unhex = value => Uint8Array.from(value.match(/../g) || [], x => parseInt(x, 16));
  const utf8 = value => new TextEncoder().encode(value);
  const plain = value => value && typeof value === "object" && !Array.isArray(value);

  async function createChannel({ secret, nonceE, nonceA, role, crypto = root.crypto, now = Date.now }) {
    if (!(secret instanceof Uint8Array) || secret.length !== 32 || !/^[0-9a-f]{32}$/.test(nonceE) ||
        !/^[0-9a-f]{32}$/.test(nonceA) || !["app", "extension"].includes(role)) throw new Error("Invalid session");
    const session = nonceE + nonceA;
    const base = await crypto.subtle.importKey("raw", secret, "HKDF", false, ["deriveKey"]);
    const derive = direction => crypto.subtle.deriveKey({ name: "HKDF", hash: "SHA-256", salt: utf8(session), info: utf8(VERSION + ":" + direction) }, base,
      { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
    const outbound = role === "app" ? "a2e" : "e2a";
    const inbound = role === "app" ? "e2a" : "a2e";
    let sendKey = await derive(outbound);
    let receiveKey = await derive(inbound);
    let sent = 0;
    let received = 0;
    let receiving = false;
    const expires = now() + TTL_MS;
    function destroy() { sendKey = null; receiveKey = null; }
    function live() {
      if (!sendKey || !receiveKey || now() >= expires) { destroy(); throw new Error("Session ended"); }
    }
    function params(direction, seq, id) {
      // Direction keys differ; each session's key is fresh. Never reuse a counter/key IV.
      const iv = new Uint8Array(12);
      new DataView(iv.buffer).setUint32(8, seq, false);
      return { name: "AES-GCM", iv, tagLength: 128, additionalData: utf8(JSON.stringify([VERSION, session, direction, seq, id])) };
    }
    return {
      destroy,
      async seal(value, id) {
        try {
          live();
          if (typeof id !== "string" || !id || id.length > 128 || !plain(value) || sent >= MAX_SEQUENCE) throw new Error("Invalid message");
          const bytes = utf8(JSON.stringify(value));
          if (bytes.length > MAX_BYTES) throw new Error("Message too large");
          const seq = ++sent;
          const data = await crypto.subtle.encrypt(params(outbound, seq, id), sendKey, bytes);
          live();
          return { type: "secure", id, session, seq, data: hex(data) };
        } catch { destroy(); throw new Error("Secure channel failed"); }
      },
      async open(packet) {
        try {
          live();
          if (receiving || !plain(packet) || Object.keys(packet).sort().join(",") !== "data,id,seq,session,type" ||
              packet.type !== "secure" || packet.session !== session || typeof packet.id !== "string" || !packet.id || packet.id.length > 128 ||
              !Number.isSafeInteger(packet.seq) || packet.seq !== received + 1 || packet.seq > MAX_SEQUENCE ||
              typeof packet.data !== "string" || packet.data.length < 32 || packet.data.length > (MAX_BYTES + 16) * 2 ||
              packet.data.length % 2 || !/^[0-9a-f]+$/.test(packet.data)) throw new Error("Invalid envelope");
          receiving = true;
          const bytes = await crypto.subtle.decrypt(params(inbound, packet.seq, packet.id), receiveKey, unhex(packet.data));
          live();
          const value = JSON.parse(new TextDecoder("utf-8", { fatal: true }).decode(bytes));
          if (!plain(value)) throw new Error("Invalid body");
          received = packet.seq;
          return value;
        } catch { destroy(); throw new Error("Secure channel failed"); }
        finally { receiving = false; }
      }
    };
  }
  const api = { createChannel, VERSION, MAX_BYTES, TTL_MS };
  root.SLVSecureChannel = api;
  if (typeof module !== "undefined" && module.exports) module.exports = api;
})(typeof self !== "undefined" ? self : globalThis);
